// Get data from the immediate previous node
const previousNodeItems = $input.all();

// Get data from "Loop Over Items" node (previous-previous node)
const loopOverItems = $('BS: LOOP').all();

// Build a Set of product_name values (lowercased, trimmed) for matching
const productNames = new Set(
  loopOverItems.map(item => (item.json.product_name || '').trim().toLowerCase())
);

const results = [];

for (const entry of previousNodeItems) {
  // Handle the case where the previous node's data is wrapped like { total, items: [...] }
  const appsList = Array.isArray(entry.json.items) ? entry.json.items : [entry.json];

  for (const app of appsList) {
    const appName = (app.name || '').trim().toLowerCase();

    if (productNames.has(appName)) {
      results.push({ json: app });
    }
  }
}

return results;

// n8n Code node - runs once per item (default mode)
const items = $input.all();
const results = [];

for (const item of items) {
  const data = item.json;
  const isEmpty = Object.keys(data).length === 0;

  results.push({
    json: {
      ...data,
      match: !isEmpty
    }
  });
}

return results;

